from typing import Iterable, List, Tuple

class IntervalSet:
    def __init__(self, intervals: Iterable[Tuple[float, float]] = None):
        # Internal representation: a list of [start, end] pairs kept normalized
        # (sorted, non-overlapping, non-adjacent). You decide how to fill it.
        self._items = []
        if intervals is not None:
            for pair in intervals:
                start, end = pair
                self.add(start, end)

    def add(self, start: float, end: float) -> None:
        """Add [start, end); merge/bridge overlapping or adjacent intervals."""
        if start >= end:
            return

        new_intervals = []
        added = False

        for s, e in self._items:
            if end <= s:
                if not added:
                    new_intervals.append((start, end))
                    added = True
                new_intervals.append((s, e))
            elif start >= e:
                new_intervals.append((s, e))
            else:
                start = min(start, s)
                end = max(end, e)

        if not added:
            new_intervals.append((start, end))

        self._items = new_intervals

    def remove(self, start: float, end: float) -> None:
        """Subtract [start, end); may shrink, delete, or split intervals."""
        if start >= end:
            return

        new_intervals = []

        for s, e in self._items:
            if end <= s or start >= e:
                new_intervals.append((s, e))
            else:
                if s < start:
                    new_intervals.append((s, start))
                if e > end:
                    new_intervals.append((end, e))

        self._items = new_intervals

    def contains(self, x: float) -> bool:
        """True iff point x lies in some stored interval."""
        for s, e in self._items:
            if s <= x < e:
                return True
        return False

    def measure(self) -> float:
        """Total length: sum of (end - start) over stored intervals."""
        return sum(e - s for s, e in self._items)

    def overlaps(self, start: float, end: float) -> bool:
        """True iff [start, end) shares a point with the set."""
        for s, e in self._items:
            if start < e and end > s:
                return True
        return False

    def intervals(self) -> List[Tuple[float, float]]:
        """Return a NEW sorted list of (start, end) tuples."""
        return self._items.copy()

